/*
 Local flatpickr shim (safe fallback)

 CDN loading removed to avoid tracking-prevention warnings. This shim
 exposes a minimal `flatpickr()` API using native date inputs and keeps
 everything self-hosted. If you need full flatpickr, serve the official
 build from your own origin instead of a third-party CDN.
*/
(function(window, document){
	'use strict';

	if (window.flatpickr) return; // don't overwrite if real flatpickr present

	function toElement(el){
		if (typeof el === 'string') return document.querySelector(el);
		return el;
	}

	function initOne(input, options){
		var el = toElement(input) || input;
		if (!el) return null;
		try{
			// prefer native date input where supported
			var origType = el.type;
			try { el.type = 'date'; } catch(e) {}

			// store metadata so destroy can restore
			var instance = {
				_el: el,
				_origType: origType,
				config: options || {},
				destroy: function(){
					try{ if (this._el && this._origType) this._el.type = this._origType; }catch(e){}
				}
			};

			// If the app expects callbacks (onChange/onClose), wire basic handlers
			if (options && typeof options.onChange === 'function'){
				el.addEventListener('change', function(ev){ try{ options.onChange.call(el, el.value, ev); }catch(e){} });
			}
			if (options && typeof options.onClose === 'function'){
				el.addEventListener('blur', function(ev){ try{ options.onClose.call(el, el.value, ev); }catch(e){} });
			}

			// Use native showPicker() where supported to reliably surface the calendar
			try{
				if (typeof el.showPicker === 'function'){
					var _pickerOpen = function(){ try{ el.showPicker(); }catch(e){} };
					el.addEventListener('click', _pickerOpen);
					el.addEventListener('focus', _pickerOpen);
					instance._pickerOpen = _pickerOpen;
				}
			}catch(e){}

			return instance;
		}catch(e){ console.debug('[flatpickr-shim] init failed', e); return null; }
	}

	function flatpickr(selectorOrElem, opts){
		// support NodeList/Array or selector string
		if (!selectorOrElem) return null;
		if (NodeList.prototype.isPrototypeOf(selectorOrElem) || Array.isArray(selectorOrElem)){
			var instances = [];
			Array.prototype.forEach.call(selectorOrElem, function(el){ var i = initOne(el, opts); if (i) instances.push(i); });
			return instances;
		}
		// single element or selector
		if (typeof selectorOrElem === 'string'){
			var nodes = document.querySelectorAll(selectorOrElem);
			var instances = [];
			Array.prototype.forEach.call(nodes, function(n){ var i = initOne(n, opts); if (i) instances.push(i); });
			return instances.length === 1 ? instances[0] : instances;
		}
		return initOne(selectorOrElem, opts);
	}

	// minimal parse/format helpers the app might call — safe defaults
	flatpickr.parseDate = function(v){ try{ return v ? new Date(v) : null; }catch(e){ return null; } };
	flatpickr.formatDate = function(d, fmt){ try{ return d ? new Date(d).toLocaleDateString() : ''; }catch(e){ return ''; } };
	flatpickr.defaultConfig = {};

	window.flatpickr = flatpickr;
})(window, document);
